package templates

import (
	"context"
	"fmt"
	"log"

	tea "github.com/charmbracelet/bubbletea"

	"github.com/anthnel/devdesk/internal/cache"
	"github.com/anthnel/devdesk/internal/command"
	"github.com/anthnel/devdesk/internal/config"
	"github.com/anthnel/devdesk/internal/jobs"
	"github.com/anthnel/devdesk/internal/scan"
	"github.com/anthnel/devdesk/internal/template"
	sharedcomponents "github.com/anthnel/devdesk/internal/ui/components"
	"github.com/anthnel/devdesk/internal/ui/shortcut"
)

// Scanning a template is scanning what it would put in a repository, and it is
// worth doing *before* that: a secret in a template ends up in every repository
// made from it.
//
// The template is fetched, written to a fixed directory of the scan cache
// (template.Materialize), and that directory is scanned like any other. It is a
// directory scan on purpose: the result is cached by path, so it appears in the
// `:sec` inventory and opens in the same results view, with nothing new to
// build. What is not reused is the workspaces list — the copy is not in it, and
// nothing here pretends it is.

const (
	reasonNoScanner   = "No scanner available — install Trivy or Gitleaks, or check scan settings"
	reasonScanRunning = "A scan of this template is already running"
)

// scanFunc runs the scanners over a directory. It is a field of the model so a
// test can answer without running Trivy.
type scanFunc func(ctx context.Context, dir string, opts scan.ScanOptions) (*scan.Result, error)

func runScanners(ctx context.Context, dir string, opts scan.ScanOptions) (*scan.Result, error) {
	return scan.NewScanner(opts).Scan(ctx, dir, scan.TargetDirectory)
}

// DepsCheckedMsg carries where the scanners resolve from on this machine.
type DepsCheckedMsg struct {
	Deps scan.DependencyStatus
}

// checkDepsCmd resolves the scanners once, off the Update goroutine.
func checkDepsCmd(cfg config.ScanConfig) tea.Cmd {
	return func() tea.Msg { return DepsCheckedMsg{Deps: scan.CheckDependencies(cfg)} }
}

// ScanStartingMsg says the scan left the queue and holds a worker. The cancel
// goes with it — it is created inside the Cmd, and stored by the registry in the
// same Update that marks the item running, so there is no window where the row
// is running and cannot be stopped (D7).
type ScanStartingMsg struct {
	Path   string
	Cancel context.CancelFunc
}

// ScanCompleteMsg is the scan's outcome.
type ScanCompleteMsg struct {
	Slug   string
	Name   string
	Path   string
	Counts scan.SeverityCounts
	// Partial is set when a stage failed and nothing was found: the scan ran, and
	// "no findings" would be a claim about something it did not look at.
	Partial bool
	Err     error
}

func (m ScanStartingMsg) Transition() jobs.Transition {
	return jobs.Transition{Kind: jobs.KindScan, Target: m.Path, State: jobs.ItemRunning, Cancel: m.Cancel}
}

func (m ScanCompleteMsg) Transition() jobs.Transition {
	t := jobs.Transition{Kind: jobs.KindScan, Target: m.Path, State: jobs.ItemDone}
	if m.Err != nil {
		t.State = jobs.ItemFailed
		t.Detail = "scan failed — check logs"
	}
	return t
}

// Compile-time proof that both can be applied to the registry: a message added
// without it is routed, updates the view, and leaves its row spinning for the
// life of the session.
var (
	_ jobs.Reporter = ScanStartingMsg{}
	_ jobs.Reporter = ScanCompleteMsg{}
)

// scanJob is everything the scan needs, read in Update and carried into the
// Cmd, which runs on another goroutine and must not reach back into the model
// (Rule 110).
type scanJob struct {
	entry template.Entry
	creds template.Credentials
	opts  scan.ScanOptions
	run   scanFunc
}

// scanTemplateCmd fetches, materializes and scans one template.
//
// contextName travels with the command rather than being read at the end (D68):
// the counts belong to the context the scan was launched in, whatever the user
// is looking at when it lands.
func scanTemplateCmd(job scanJob, contextName string) tea.Cmd {
	dir, dirErr := template.ScanDir(job.entry.Slug)
	ctx, cancel := context.WithCancel(context.Background())

	return tea.Sequence(
		func() tea.Msg { return ScanStartingMsg{Path: dir, Cancel: cancel} },
		func() tea.Msg {
			defer cancel()
			complete := ScanCompleteMsg{Slug: job.entry.Slug, Name: job.entry.Name, Path: dir}

			if dirErr != nil {
				complete.Err = dirErr
				return complete
			}
			result, err := job.scanOnce(ctx, contextName)
			if err != nil {
				log.Printf("ERROR [templates] scan %s: %v", job.entry.Slug, err)
				complete.Err = err
				return complete
			}
			complete.Counts = result.Counts
			complete.Partial = len(result.Errors) > 0 && result.TotalFindings() == 0
			return complete
		},
	)
}

func (j scanJob) scanOnce(ctx context.Context, contextName string) (*scan.Result, error) {
	files, err := template.Fetch(ctx, j.entry.Source, j.creds)
	if err != nil {
		return nil, fmt.Errorf("fetching the template: %w", err)
	}
	dir, err := template.Materialize(j.entry.Slug, files)
	if err != nil {
		return nil, fmt.Errorf("writing the template: %w", err)
	}
	result, err := j.run(ctx, dir, j.opts)
	if err != nil {
		return nil, err
	}
	if _, err := cache.StoreWorkspaceScan(contextName, dir, result); err != nil {
		// The scan happened and its counts are reported; only the cache write
		// failed, and `:sec` will not show it.
		log.Printf("ERROR [templates] store scan %s: %v", j.entry.Slug, err)
	}
	return result, nil
}

// scanOptions assembles the options for a template: the configured scanners,
// and no CI score — a template is not a repository with a pipeline to grade, and
// plumber would go looking for a remote it does not have.
func (m Model) scanOptions() scan.ScanOptions {
	opts := scan.OptionsFromConfig(m.config)
	opts.EnableCIScore = false
	return opts
}

// scannerState says whether a scan can run at all on this machine. Not knowing
// is not knowing that not: until the check comes back the key stays lit, since
// greying it for a few frames only to un-grey it reads as a fault (Rule 130).
func (m Model) scannerState() shortcut.Availability {
	if m.deps == nil || m.deps.TrivyAvailable || m.deps.GitleaksAvailable {
		return shortcut.Availability{}
	}
	return shortcut.Unavailable(reasonNoScanner)
}

// scanning reports whether a scan of this directory is live, wherever it was
// started — the registry is one bookkeeping.
func (m Model) scanning(dir string) bool {
	for _, run := range jobs.Unfinished(m.jobs) {
		if run.Kind != jobs.KindScan {
			continue
		}
		for _, item := range run.Items {
			if item.Target == dir && !item.State.Terminal() {
				return true
			}
		}
	}
	return false
}

// startScan launches a scan of the selected template.
func (m Model) startScan() (tea.Model, tea.Cmd) {
	if reason := m.refusal(m.availability().Scan); reason != "" {
		cmd := m.footer.Warn(reason)
		return m, cmd
	}
	entry, _ := m.selectedEntry()
	dir, err := template.ScanDir(entry.Slug)
	if err != nil {
		log.Printf("ERROR [templates] scan directory for %s: %v", entry.Slug, err)
		cmd := m.footer.Error("Could not scan the template — check logs")
		return m, cmd
	}

	job := scanJob{
		entry: entry,
		creds: template.CredentialsFor(m.config, m.secrets, entry.Source),
		opts:  m.scanOptions(),
		run:   m.scanner,
	}
	run := jobs.NewRun(jobs.KindScan, command.ViewTemplates, "", entry.Name, dir)
	return m, jobs.StartInContext(run, func(contextName string) tea.Cmd {
		return scanTemplateCmd(job, contextName)
	})
}

func (m Model) handleJobsChanged(msg jobs.ChangedMsg) (tea.Model, tea.Cmd) {
	m.jobs = msg.Runs
	m.footer.SetSpinnerFrame(msg.RenderedFrame)
	return m, nil
}

// handleScanComplete says how the scan ended. The counts are in the footer and
// the report is in `:sec`, where this directory is listed like any other scanned
// target.
func (m Model) handleScanComplete(msg ScanCompleteMsg) (tea.Model, tea.Cmd) {
	var cmd tea.Cmd
	switch {
	case msg.Err != nil:
		cmd = m.footer.Error("Scan of " + msg.Name + " failed — check logs")
	case msg.Partial:
		cmd = m.footer.Warn("Scanned " + msg.Name + ", but a scan stage failed — check logs")
	default:
		cmd = m.footer.Info(scanSummary(msg))
	}
	return m, cmd
}

// scanSummary is the one line a finished scan leaves.
func scanSummary(msg ScanCompleteMsg) string {
	c := msg.Counts
	if c.Critical+c.High+c.Medium+c.Low == 0 {
		return "Scanned " + msg.Name + " — no findings"
	}
	return fmt.Sprintf("Scanned %s — %d critical, %d high, %d medium, %d low — :sec for the report",
		msg.Name, c.Critical, c.High, c.Medium, c.Low)
}

// jobsStatus is the footer's derived line while work is live.
func (m Model) jobsStatus() sharedcomponents.Status {
	if text := sharedcomponents.JobsStatusLine(m.jobs, command.ViewTemplates); text != "" {
		return sharedcomponents.Status{Text: text, Spinner: true}
	}
	return sharedcomponents.Status{}
}

package templates

import (
	"fmt"
	"strings"

	"github.com/charmbracelet/bubbles/textinput"
	tea "github.com/charmbracelet/bubbletea"
	"github.com/charmbracelet/lipgloss"

	"github.com/anthnel/devdesk/internal/template"
	sharedcomponents "github.com/anthnel/devdesk/internal/ui/components"
	"github.com/anthnel/devdesk/internal/ui/theme"
)

// formField names one control of the form. The fields on screen depend on the
// source's kind, so focus is an index into fields(), not one of these.
type formField int

const (
	fieldName formField = iota
	fieldDescription
	fieldTags
	fieldKind
	fieldURL
	fieldPath
	fieldRef
	fieldSubmit
)

const (
	descriptionWrapWidth = 80
	descriptionCharLimit = 250
)

// entryForm creates or edits a catalog entry. It is shown in the viewport, not
// as a modal (Rule 112).
type entryForm struct {
	name, tags, url, path, ref textinput.Model
	description                sharedcomponents.WrappedInput

	kind  int // index into template.Kinds
	focus int // index into fields()

	// editing fixes the slug. Creating derives it from the name, so renaming a
	// template does not silently orphan whatever remembered its old slug.
	editing bool
	slug    string
	// taken reports whether a slug already names a declared entry.
	taken func(slug string) bool

	err   string
	width int
}

// newEntryForm opens the form empty, or prefilled from an entry to edit it.
func newEntryForm(entry *template.Entry, taken func(string) bool) *entryForm {
	f := &entryForm{
		name:        newInput("Spring Boot API", 100),
		tags:        newInput("java, spring-boot", 200),
		url:         newInput("", 300),
		path:        newInput("", 300),
		ref:         newInput("", 100),
		description: sharedcomponents.NewWrappedInput(descriptionWrapWidth, descriptionCharLimit, "description (optional)"),
		taken:       taken,
	}

	if entry != nil {
		f.editing = true
		f.slug = entry.Slug
		f.name.SetValue(entry.Name)
		f.description.SetValue(entry.Description)
		f.tags.SetValue(strings.Join(entry.Tags, ", "))
		f.url.SetValue(entry.Source.URL)
		f.path.SetValue(entry.Source.Path)
		f.ref.SetValue(entry.Source.Ref)
		for i, k := range template.Kinds {
			if k == entry.Source.Kind {
				f.kind = i
			}
		}
	}

	f.updateFocus()
	return f
}

func newInput(placeholder string, limit int) textinput.Model {
	in := textinput.New()
	in.Placeholder = placeholder
	in.CharLimit = limit
	in.Width = 60
	theme.StyleTextInput(&in)
	return in
}

// SetWidth is called from the window-size handler.
func (f *entryForm) SetWidth(width int) {
	f.width = width
	f.description.SetDisplayWidth(width)
}

func (f *entryForm) currentKind() template.Kind { return template.Kinds[f.kind] }

// fields lists what is on screen, in order. A local template has no URL, so the
// field is absent rather than disabled: it is not that it cannot be filled, it
// is that it means nothing.
func (f *entryForm) fields() []formField {
	list := []formField{fieldName, fieldDescription, fieldTags, fieldKind}
	if f.currentKind() != template.KindLocal {
		list = append(list, fieldURL)
	}
	return append(list, fieldPath, fieldRef, fieldSubmit)
}

func (f *entryForm) focused() formField { return f.fields()[f.focus] }

// Cycling is only meaningful on the kind field; the header greys ←→ elsewhere.
func (f *entryForm) OnCycleField() bool { return f.focused() == fieldKind }

func (f *entryForm) updateFocus() {
	f.name.Blur()
	f.tags.Blur()
	f.url.Blur()
	f.path.Blur()
	f.ref.Blur()
	f.description.Blur()

	switch f.focused() {
	case fieldName:
		f.name.Focus()
	case fieldDescription:
		f.description.Focus()
	case fieldTags:
		f.tags.Focus()
	case fieldURL:
		f.url.Focus()
	case fieldPath:
		f.path.Focus()
	case fieldRef:
		f.ref.Focus()
	}
}

// InEditMode is always true while the form is open: `:` is a character in a URL.
func (f *entryForm) InEditMode() bool { return true }

// Update handles a key. Keys follow Rule 135: ↑↓ move between fields, ←→ cycle
// the kind, tab does nothing, enter advances or confirms.
func (f *entryForm) Update(msg tea.KeyMsg) tea.Cmd {
	switch msg.String() {
	case "esc":
		return func() tea.Msg { return FormCancelMsg{} }

	case "down":
		f.move(1)
		return nil

	case "up":
		f.move(-1)
		return nil

	case "tab", "shift+tab":
		return nil

	case "enter":
		if f.focused() == fieldSubmit {
			return f.submit()
		}
		f.move(1)
		return nil

	case "left", "right":
		if f.focused() == fieldKind {
			f.cycleKind(msg.String() == "right")
			return nil
		}
	}

	return f.forward(msg)
}

func (f *entryForm) move(delta int) {
	n := len(f.fields())
	f.focus = (f.focus + delta + n) % n
	f.updateFocus()
}

// cycleKind moves to the next or previous kind. The focus stays on the kind
// field, which sits above every field that changes.
func (f *entryForm) cycleKind(forward bool) {
	n := len(template.Kinds)
	if forward {
		f.kind = (f.kind + 1) % n
	} else {
		f.kind = (f.kind - 1 + n) % n
	}
	f.err = ""
}

func (f *entryForm) forward(msg tea.KeyMsg) tea.Cmd {
	var cmd tea.Cmd
	switch f.focused() {
	case fieldName:
		f.name, cmd = f.name.Update(msg)
	case fieldDescription:
		f.description, cmd = f.description.Update(msg)
	case fieldTags:
		f.tags, cmd = f.tags.Update(msg)
	case fieldURL:
		f.url, cmd = f.url.Update(msg)
	case fieldPath:
		f.path, cmd = f.path.Update(msg)
	case fieldRef:
		f.ref, cmd = f.ref.Update(msg)
	}
	return cmd
}

// entry is what the form currently describes.
func (f *entryForm) entry() (template.Entry, error) {
	slug := f.slug
	if !f.editing {
		slug = slugify(f.name.Value())
	}

	src := template.Source{Kind: f.currentKind(), Path: strings.TrimSpace(f.path.Value()), Ref: strings.TrimSpace(f.ref.Value())}
	if src.Kind != template.KindLocal {
		src.URL = strings.TrimSpace(f.url.Value())
	}

	e := template.Entry{
		Slug:        slug,
		Name:        strings.TrimSpace(f.name.Value()),
		Description: strings.TrimSpace(f.description.Value()),
		Tags:        template.NormalizeTags(strings.Split(f.tags.Value(), ",")),
		Source:      src,
	}
	if slug == "" {
		return e, fmt.Errorf("the name needs a letter or a digit")
	}
	if !f.editing && f.taken != nil && f.taken(slug) {
		return e, fmt.Errorf("a template named %q already exists", slug)
	}
	return e, e.Validate()
}

// submit validates in place: an invalid entry keeps the form open with the
// reason, rather than sending a message the view would only turn back.
func (f *entryForm) submit() tea.Cmd {
	e, err := f.entry()
	if err != nil {
		f.err = err.Error()
		return nil
	}
	f.err = ""
	return func() tea.Msg { return FormSubmitMsg{Entry: e} }
}

// slugify makes the identifier of a new entry from its name.
func slugify(name string) string {
	var b strings.Builder
	dash := false
	for _, r := range strings.ToLower(name) {
		switch {
		case r >= 'a' && r <= 'z', r >= '0' && r <= '9':
			if dash && b.Len() > 0 {
				b.WriteByte('-')
			}
			dash = false
			b.WriteRune(r)
		default:
			dash = true
		}
	}
	return b.String()
}

// GetTitle is the form's breadcrumb.
func (f *entryForm) GetTitle() string {
	if f.editing {
		return "Edit template"
	}
	return "New template"
}

// View renders the form: one blank line of top padding (Rule 131), then the
// fields with the focus marker (Rule 120).
func (f *entryForm) View() string {
	var b strings.Builder
	b.WriteString(theme.EmptyLineBg(f.width) + "\n")

	if f.err != "" {
		b.WriteString(lipgloss.NewStyle().Background(theme.ColorBackground).Foreground(theme.ColorError).Render("Error: "+f.err) + "\n\n")
	}

	labels := f.labels()
	for _, field := range f.fields() {
		switch field {
		case fieldName:
			b.WriteString(f.line(field, "Name", f.name.View()) + "\n")
		case fieldDescription:
			b.WriteString(f.descriptionBlock() + "\n\n")
		case fieldTags:
			b.WriteString(f.line(field, "Tags", f.tags.View()) + "\n")
		case fieldKind:
			b.WriteString(f.kindLine() + "\n")
		case fieldURL:
			b.WriteString(f.line(field, labels.url, f.url.View()) + "\n")
		case fieldPath:
			b.WriteString(f.line(field, labels.path, f.path.View()) + "\n")
		case fieldRef:
			b.WriteString(f.line(field, labels.ref, f.ref.View()) + "\n")
		case fieldSubmit:
			label := "Create"
			if f.editing {
				label = "Save"
			}
			b.WriteString("\n  " + theme.RenderButton(label, true, "primary") + "\n")
		}
	}
	return b.String()
}

// kindLabels names the three source fields for the kind on screen. The same
// three inputs serve every kind — a value typed before cycling the kind is kept
// — and only what they are called changes.
type kindLabels struct{ url, path, ref string }

func (f *entryForm) labels() kindLabels {
	switch f.currentKind() {
	case template.KindLocal:
		return kindLabels{path: "Directory", ref: "Branch, tag or SHA"}
	case template.KindOCI:
		return kindLabels{url: "Registry URL", path: "Repository", ref: "Tag"}
	default:
		return kindLabels{url: "Clone URL", path: "Subdirectory", ref: "Branch, tag or SHA"}
	}
}

// line renders a single-line field: label and value on the same line (Rule 113).
func (f *entryForm) line(field formField, label, value string) string {
	if f.focused() == field {
		return theme.KeyStyle.Render(theme.IconCircleSmall+" "+label+" "+theme.IconChevronRight+" ") + value
	}
	return theme.Bg("  "+label+" "+theme.IconChevronRight+" ") + value
}

// kindLine is the ←→ cycle field (Rule 132).
func (f *entryForm) kindLine() string {
	label := "Source " + theme.IconSelect + " "
	value := lipgloss.NewStyle().Background(theme.ColorBackground).Foreground(theme.ColorText).Render(string(f.currentKind()))
	if f.focused() == fieldKind {
		return theme.KeyStyle.Render(theme.IconCircleSmall+" "+label+theme.IconChevronRight+" ") + value
	}
	return theme.Bg("  "+label+theme.IconChevronRight+" ") + value
}

// descriptionBlock is the multi-line field: label, then the wrapped input.
func (f *entryForm) descriptionBlock() string {
	label := theme.Bg("  Description " + theme.IconChevronRight)
	if f.focused() == fieldDescription {
		label = theme.KeyStyle.Render(theme.IconCircleSmall + " Description " + theme.IconChevronRight)
	}
	return label + "\n" + f.description.View()
}

